tool_calls.arguments_json:
{"function":"() => {
  const text = document.body.innerText;
  // Split by SKU:
  // Each product block has ASIN: ..., FNSKU: ..., SKU: ...
  const lines = text.split('\n');
  const products = [];

  // We can also find product blocks by regex matching
  // Let's find all occurrences of "ASIN: [A-Z0-9]{10}"
  const asinIndices = [];
  const asinRegex = /ASIN:\s*([A-Z0-9]{10})/g;
  let match;
  while ((match = asinRegex.exec(text)) !== null) {
    asinIndices.push({ asin: match[1], index: match.index });
  }

  for (let i = 0; i < asinIndices.length; i++) {
    const start = asinIndices[i].index;
    const end = (i + 1 < asinIndices.length) ? asinIndices[i+1].index : text.length;
    const block = text.slice(Math.max(0, start - 200), end);

    const asin = asinIndices[i].asin;
    const skuMatch = block.match(/SKU:\s*([^\n\r]+)/);
    const sku = skuMatch ? skuMatch[1].trim() : '';

    const fnskuMatch = block.match(/FNSKU:\s*([^\n\r]+)/);
    const fnsku = fnskuMatch ? fnskuMatch[1].trim() : '';

    // Title is usually before ASIN
    const preAsin = block.slice(0, block.indexOf('ASIN:'));
    const preLines = preAsin.split('\n').map(l => l.trim()).filter(l => l && !l.includes('供应商') && !l.includes('AWD') && !l.includes('建议操作'));
    const title = preLines.length > 0 ? preLines[preLines.length - 1] : '';

    // FBA inventory on-hand: "现有 \t(\d+)"
    const onHandMatch = block.match(/现有\s*[:\t]?\s*(\d+)/);
    const onHand = onHandMatch ? parseInt(onHandMatch[1], 10) : 0;

    // Excess units: "(\d+)\s*件预计冗余商品" or "预计冗余商品数量\s*\n\s*(\d+)" or similar
    let excess = 0;
    const excessMatch = block.match(/(\d+)\s*件预计冗余商品/) || block.match(/预计冗余商品数量[^\n]*\n\s*(\d+)/);
    if (excessMatch) {
      excess = parseInt(excessMatch[1], 10);
    } else {
      // Sometimes just a standalone number between DoS and 0-60:
      // like: "详情 \n 59 \n 0-60:0"
      const m = block.match(/DoS[^\n]*\n[^\n]*\n\s*(\d+)\s*\n\s*0-60:/);
      if (m) excess = parseInt(m[1], 10);
    }

    // Age buckets:
    // 0-60:(\d+) 61-90:(\d+) 91-180:(\d+) 181-330:(\d+) 331-365:(\d+) 366~455:(\d+) 456 以上:(\d+)
    const ageMatch = block.match(/0-60:(\d+)\s*61-90:(\d+)\s*91-180:(\d+)\s*181-330:(\d+)\s*331-365:(\d+)\s*366~455:(\d+)\s*456 以上:(\d+)/);
    let age = null;
    let over180 = 0;
    let over365 = 0;
    if (ageMatch) {
      age = {
        d0_60: parseInt(ageMatch[1], 10),
        d61_90: parseInt(ageMatch[2], 10),
        d91_180: parseInt(ageMatch[3], 10),
        d181_330: parseInt(ageMatch[4], 10),
        d331_365: parseInt(ageMatch[5], 10),
        d366_455: parseInt(ageMatch[6], 10),
        d456_plus: parseInt(ageMatch[7], 10)
      };
      over180 = age.d181_330 + age.d331_365 + age.d366_455 + age.d456_plus;
      over365 = age.d366_455 + age.d456_plus;
    }

    // Surcharge
    let surcharge = 0;
    const surMatch = block.match(/总额:\s*(?:US)?\$([0-9\.,]+)/i) || block.match(/超龄库存附加费:\s*(?:US)?\$([0-9\.,]+)/i);
    if (surMatch && surMatch[1] && surMatch[1] !== '--') {
      surcharge = parseFloat(surMatch[1].replace(/,/g, '')) || 0;
    }

    products.push({
      title: title.slice(0, 60),
      asin,
      sku,
      onHand,
      excess,
      over180,
      over365,
      surcharge,
      age
    });
  }

  // Filter products that have inventory or issues
  const withInventory = products.filter(p => p.onHand > 0 || p.excess > 0 || p.over180 > 0);
  const withExcess = products.filter(p => p.excess > 0);
  const withOver180 = products.filter(p => p.over180 > 0);
  const withOver365 = products.filter(p => p.over365 > 0);
  const totalSurcharge = products.reduce((sum, p) => sum + p.surcharge, 0);
  const totalExcess = products.reduce((sum, p) => sum + p.excess, 0);

  return {
    totalParsed: products.length,
    withInventoryCount: withInventory.length,
    withExcessCount: withExcess.length,
    totalExcessUnits: totalExcess,
    withOver180Count: withOver180.length,
    withOver365Count: withOver365.length,
    totalEstimatedSurcharge: totalSurcharge.toFixed(2),
    excessSample: withExcess.slice(0, 15),
    over180Sample: withOver180.slice(0, 15)
  };
}","pageId":9,"toolSummary":"Parse all products inventory health and age"}

