{"function":"() => {
  const katInput = document.querySelector('kat-input[unique-id="katal-id-26"]');
  const shadow = katInput.shadowRoot;
  const shadowInput = shadow ? shadow.querySelector('input') : null;

  if (shadowInput) {
    shadowInput.focus();
    shadowInput.dispatchEvent(new Event('input', { bubbles: true, composed: true }));
    shadowInput.dispatchEvent(new Event('change', { bubbles: true, composed: true }));
    shadowInput.dispatchEvent(new KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, which: 13, bubbles: true, composed: true }));
    shadowInput.blur();
    katInput.dispatchEvent(new Event('change', { bubbles: true, composed: true }));
    return 'dispatched events';
  }
  return 'no shadow input';
}","pageId":1,"toolSummary":"Dispatch change and enter on price input"}

